// CreateGlobalClusterMessage represents the CreateGlobalClusterMessage schema from the OpenAPI specification
type CreateGlobalClusterMessage struct {
	Databasename interface{} `json:"DatabaseName,omitempty"` // <p>The name for your database of up to 64 alphanumeric characters. If you don't specify a name, Amazon Aurora doesn't create a database in the global database cluster.</p> <p>Constraints:</p> <ul> <li> <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the database name from the source DB cluster.</p> </li> </ul>
	Deletionprotection interface{} `json:"DeletionProtection,omitempty"` // Specifies whether to enable deletion protection for the new global database cluster. The global database can't be deleted when deletion protection is enabled.
	Engine interface{} `json:"Engine,omitempty"` // <p>The database engine to use for this global database cluster.</p> <p>Valid Values: <code>aurora-mysql | aurora-postgresql</code> </p> <p>Constraints:</p> <ul> <li> <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the engine of the source DB cluster.</p> </li> </ul>
	Engineversion interface{} `json:"EngineVersion,omitempty"` // <p>The engine version to use for this global database cluster.</p> <p>Constraints:</p> <ul> <li> <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the engine version of the source DB cluster.</p> </li> </ul>
	Globalclusteridentifier interface{} `json:"GlobalClusterIdentifier,omitempty"` // The cluster identifier for this global database cluster. This parameter is stored as a lowercase string.
	Sourcedbclusteridentifier interface{} `json:"SourceDBClusterIdentifier,omitempty"` // <p>The Amazon Resource Name (ARN) to use as the primary cluster of the global database.</p> <p>If you provide a value for this parameter, don't specify values for the following settings because Amazon Aurora uses the values from the specified source DB cluster:</p> <ul> <li> <p> <code>DatabaseName</code> </p> </li> <li> <p> <code>Engine</code> </p> </li> <li> <p> <code>EngineVersion</code> </p> </li> <li> <p> <code>StorageEncrypted</code> </p> </li> </ul>
	Storageencrypted interface{} `json:"StorageEncrypted,omitempty"` // <p>Specifies whether to enable storage encryption for the new global database cluster.</p> <p>Constraints:</p> <ul> <li> <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the setting from the source DB cluster.</p> </li> </ul>
}

